<?php /** @var \Sysfera\Plugin $sf @var \SysferaStoragerent\Ctx $ctx @var string $lang @var array $k @var array $versions @var array $docs @var array $invoices @var bool $canWrite @var bool $staff @var string $today @var bool $tenantView */
