<div class="card"><div class="row sr-between"><div><h2 style="margin:0"><?= e($k['number']) ?> <span class="badge <?= e(sr_cls($k['state'])) ?>"><?= e($sf->t('st_' . $k['state'])) ?></span></h2><p class="muted"><a href="<?= e($sf->url('/tenant/' . $k['tenant_id'])) ?>"><?= e($t['name'] ?? '') ?></a></p></div>
