  <dl class="sr-dl">
    <dt><?= e($sf->t('col_period')) ?></dt><dd><?= e(sr_d($k['start_date'])) ?> – <?= e(sr_d($k['end_date'])) ?><?php if ($k['terminated_on']): ?> <small class="muted">(<?= e($sf->t('terminated_on', ['date' => sr_d($k['terminated_on'])])) ?>: <?= e($k['termination_reason']) ?>)</small><?php endif; ?></dd>
