    <dt><?= e($sf->t('f_rate')) ?></dt><dd><?= e(sr_m($k['rate'], $lang)) ?> / <?= e($sf->t('rt_' . $k['rate_type'])) ?> · <b><?= e(sr_m($k['monthly'], $lang)) ?></b> <?= e($sf->t('per_month')) ?></dd>
    <dt><?= e($sf->t('f_billing')) ?></dt><dd><?= e($sf->t('billing_every', ['n' => $k['billing_months']])) ?> · <?= e($sf->t('f_due_day')) ?>: <?= (int)$k['due_day'] ?> · <?= e($sf->t('f_grace')) ?>: <?= (int)$k['grace_days'] ?></dd>
