    <dt><?= e($sf->t('f_deposit')) ?></dt><dd><?= e(sr_m($k['deposit'], $lang)) ?></dd>
    <dt><?= e($sf->t('f_utilities')) ?></dt><dd><?= e($sf->t('um_' . $k['util_method'])) ?><?= $k['util_method'] === 'fixed' ? ' · ' . e(sr_m($k['util_fixed'], $lang)) : '' ?></dd>
    <dt><?= e($sf->t('f_access')) ?></dt><dd><?= $k['access_24h'] ? e($sf->t('access_24h')) : e($k['access_from'] . ' – ' . $k['access_to']) ?></dd>
    <dt><?= e($sf->t('f_notice')) ?></dt><dd><?= e($sf->t('days_n', ['n' => $k['notice_days']])) ?></dd>
    <?php if ($k['note'] !== ''): ?><dt><?= e($sf->t('f_note')) ?></dt><dd><?= nl2br(e($k['note'])) ?></dd><?php endif; ?>
