<?php if ($canWrite): ?>
<div class="grid2">
<?php if ($k['status'] === 'draft'): ?><form method="post" action="<?= e($sf->url('/contract/' . $id . '/do')) ?>" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="activate"><h3><?= e($sf->t('contract_activate')) ?></h3><p class="muted sm"><?= e($sf->t('contract_activate_help')) ?></p><button class="btn primary"><?= e($sf->t('contract_activate')) ?></button></form><?php endif; ?>
<?php if ($k['status'] === 'active'): ?>
<form method="post" action="<?= e($sf->url('/contract/' . $id . '/do')) ?>" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="renew"><h3><?= e($sf->t('contract_renew')) ?></h3><p class="muted sm"><?= e($sf->t('contract_renew_help')) ?></p>
  <div class="sr-2"><?= sr_in('end_date', $sf->t('f_new_end'), '', 'date') ?><?= sr_in('rate', $sf->t('f_new_rate'), '', 'text', 'inputmode="decimal"') ?></div><button class="btn primary"><?= e($sf->t('contract_renew')) ?></button></form>
<form method="post" action="<?= e($sf->url('/contract/' . $id . '/do')) ?>" class="card" onsubmit="return confirm('<?= e($sf->t('confirm_terminate')) ?>')"><?= csrf_field() ?><input type="hidden" name="do" value="terminate"><h3><?= e($sf->t('contract_terminate')) ?></h3>
  <div class="sr-2"><?= sr_in('date', $sf->t('f_term_date'), $today, 'date', 'required') ?><?= sr_in('reason', $sf->t('f_reason'), '', 'text', 'required maxlength="255"') ?></div><button class="btn danger"><?= e($sf->t('contract_terminate')) ?></button></form>
<form method="post" action="<?= e($sf->url('/contract/' . $id . '/do')) ?>" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="penalties"><h3><?= e($sf->t('penalties_bill')) ?></h3><p class="muted sm"><?= e($sf->t('penalties_bill_help')) ?></p><button class="btn"><?= e($sf->t('penalties_bill')) ?></button></form>
<?php endif; ?></div><?php endif; ?>
<?php if ($invoices): ?><div class="card"><h3><?= e($sf->t('wrms_invoices')) ?></h3><div class="sr-scroll"><table><thead><tr><th><?= e($sf->t('col_invoice')) ?></th><th><?= e($sf->t('col_period')) ?></th><th><?= e($sf->t('col_due_date')) ?></th><th><?= e($sf->t('col_total')) ?></th><th><?= e($sf->t('col_outstanding')) ?></th><th><?= e($sf->t('col_status')) ?></th></tr></thead><tbody>
  <?php foreach ($invoices as $i): ?><tr><td><a href="<?= e($sf->url('/invoice/' . $i['id'])) ?>"><?= e($i['number']) ?></a></td><td><?= e($i['period_start'] ? sr_d($i['period_start']) . ' – ' . sr_d($i['period_end']) : $sf->t('inv_manual')) ?></td><td><?= e(sr_d($i['due_date'])) ?></td><td><?= e(sr_m($i['total'], $lang)) ?></td><td><?= e(sr_m($i['outstanding'], $lang)) ?></td><td><span class="badge <?= e(sr_cls($i['status'])) ?>"><?= e($sf->t('st_' . $i['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<div class="card"><h3><?= e($sf->t('wrms_documents')) ?></h3>
  <?php if ($docs): ?><table><tbody><?php foreach ($docs as $d): ?><tr><td><a href="<?= e($sf->url('/doc/' . $d['id'])) ?>"><?= e($d['title']) ?></a> <small class="muted"><?= e($d['file_name']) ?></small></td><td><?= e(sr_dt((int)$d['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table><?php else: ?><p class="muted"><?= e($sf->t('none')) ?></p><?php endif; ?>
  <?php if ($canWrite): ?><form method="post" enctype="multipart/form-data" action="<?= e($sf->url('/doc/upload')) ?>" class="sr-inline"><?= csrf_field() ?><input type="hidden" name="owner_type" value="contract"><input type="hidden" name="owner_id" value="<?= $id ?>"><input type="hidden" name="kind" value="signed"><input type="hidden" name="back" value="<?= e('/p/storagerent/contract/' . $id) ?>">
    <input name="title" placeholder="<?= e($sf->t('doc_title_signed')) ?>" maxlength="190"><input type="file" name="file" required><button class="btn"><?= e($sf->t('upload')) ?></button></form><?php endif; ?></div>
<?php if ($versions): ?><div class="card"><h3><?= e($sf->t('versions')) ?></h3><table><thead><tr><th>#</th><th><?= e($sf->t('col_date')) ?></th><th><?= e($sf->t('col_action')) ?></th><th><?= e($sf->t('f_rate')) ?></th><th><?= e($sf->t('col_period')) ?></th></tr></thead><tbody>
  <?php foreach ($versions as $v): $tm = $v['data']['terms'] ?? []; ?><tr><td><?= (int)$v['version'] ?></td><td><?= e(sr_dt((int)$v['created_at'])) ?></td><td><?= e($v['note']) ?></td><td><?= e(sr_m((int)($tm['rate'] ?? 0), $lang)) ?></td><td><?= e(sr_d($tm['start_date'] ?? '')) ?> – <?= e(sr_d($tm['end_date'] ?? '')) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
